-- One row per hotel, four named columns
SELECT id, city, name, stars
FROM hotels;

-- Aliases become the JSON keys the frontend reads
SELECT name AS hotel_name, DATEDIFF(end_date, start_date) AS nights
FROM bookings;

-- Hotels with at least four stars in one city
SELECT id, name, stars
FROM hotels
WHERE city = 'Budapest' AND stars >= 4;

-- NULL never matches =; use IS NULL
SELECT email, first_name FROM customers WHERE phone IS NULL;

-- Wrong: Budapest any stars, or Debrecen with five stars
SELECT id, name FROM hotels
WHERE city = 'Budapest' OR city = 'Debrecen' AND stars = 5;

-- Right: either city, and at least four stars in both
SELECT id, name FROM hotels
WHERE (city = 'Budapest' OR city = 'Debrecen') AND stars >= 4;

-- Stars from 3 to 5, both ends counted
SELECT id, name, stars FROM hotels
WHERE stars BETWEEN 3 AND 5;

-- Dates: a booking starting on the 31st is inside the range
SELECT customer_email, start_date FROM bookings
WHERE start_date BETWEEN '2025-07-01' AND '2025-07-31';

-- One guest, all columns named
INSERT INTO customers (email, first_name, last_name, phone, birthday, image)
