CREATE INDEX idx_hotels_owner   ON hotels (owner_email);

-- Composite index: usable for hotel_id alone, or hotel_id plus a date,
-- but not for start_date alone, because that column is not leftmost.
CREATE INDEX idx_bookings_hotel_date ON bookings (hotel_id, start_date);

// Wrong: the request writes part of the statement
const badSql = `SELECT * FROM hotels WHERE city = '${req.query.city}'`;

// Right: the driver escapes and binds the value
const [rows] = await pool.execute(
    'SELECT * FROM hotels WHERE city = ?',
    [req.query.city]
);

// A column name cannot be bound. Whitelist it, then inline the safe name.
const sort = ['name', 'city', 'stars'].includes(req.query.sort) ? req.query.sort : 'name';
const [sorted] = await pool.query(`SELECT id, name FROM hotels ORDER BY ${sort}`);

const [result] = await pool.execute(
    'INSERT INTO hotels (city, name, description, stars, owner_email) VALUES (?, ?, ?, ?, ?)',
    [city, name, description, stars, ownerEmail]
);

// 201 with the new key for a create
res.status(201).json({ id: result.insertId });

// 404 when an update or delete matched nothing
